'use client'

import { useEffect, useState } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import { auth, db } from '@/lib/firebase'
import { onAuthStateChanged, User, signOut } from 'firebase/auth'
import { doc, onSnapshot } from 'firebase/firestore'
import { LayoutDashboard, LogOut, MessageSquare, Activity, Settings, BookOpen, FileText, PieChart } from 'lucide-react'

export default function AdminLayout({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [loading, setLoading] = useState(true)
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)
  const router = useRouter()
  const pathname = usePathname()

  useEffect(() => {
    if (!auth) {
      setLoading(false)
      return
    }

    let unsubscribeSession: () => void;

    const unsubscribeAuth = onAuthStateChanged(auth, (user) => {
      if (user) {
        setUser(user)

        // Single session enforcement (skip on login page to prevent race condition during login)
        if (db && pathname !== '/admin/login') {
           unsubscribeSession = onSnapshot(doc(db, 'admin_settings', 'active_session'), (docSnap) => {
              if (docSnap.exists()) {
                 const data = docSnap.data()
                 const currentSession = localStorage.getItem('sizesnap_admin_session')
                 if (data.sessionId && data.sessionId !== currentSession) {
                    console.log('Another device logged in. Logging out...')
                    alert('You have been logged out because this admin account was accessed from another device.')
                    signOut(auth)
                 }
              }
           })
        }
      } else {
        setUser(null)
        if (pathname !== '/admin/login') {
          router.push('/admin/login')
        }
      }
      setLoading(false)
    })

    return () => {
      unsubscribeAuth()
      if (unsubscribeSession) unsubscribeSession()
    }
  }, [pathname, router])

  // Close mobile menu on route change
  useEffect(() => {
    setMobileMenuOpen(false)
  }, [pathname])

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#FAFAFA] dark:bg-black">
        <div className="w-5 h-5 border-2 border-zinc-900 dark:border-white border-t-transparent rounded-full animate-spin"></div>
      </div>
    )
  }

  if (pathname === '/admin/login') {
    return <>{children}</>
  }

  if (!user) return null

  const navItems = [
    { name: 'Dashboard', href: '/admin', icon: LayoutDashboard },
    { name: 'Tools', href: '/admin/tools', icon: Activity },
    { name: 'SEO', href: '/admin/seo', icon: PieChart },
    { name: 'Feedback', href: '/admin/feedback', icon: MessageSquare },
    { name: 'Content', href: '/admin/content', icon: BookOpen },
    { name: 'Settings', href: '/admin/settings', icon: Settings },
  ]

  return (
    <div className="min-h-screen bg-[#FAFAFA] dark:bg-black flex font-sans selection:bg-zinc-200 dark:selection:bg-zinc-800 text-zinc-900 dark:text-zinc-100">
      {/* Mobile Menu Overlay */}
      {mobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 lg:hidden" 
          onClick={() => setMobileMenuOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 w-64 bg-[#FAFAFA] dark:bg-black border-r border-zinc-200 dark:border-zinc-800 flex flex-col z-50 transform transition-transform duration-300 ease-in-out ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="px-6 py-6 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="relative w-7 h-7 bg-white rounded-md border border-zinc-200 dark:border-zinc-800 flex items-center justify-center overflow-hidden shrink-0 shadow-sm">
               <img src="/logo.png" alt="SizeSnap Logo" className="w-full h-full object-contain" onError={(e) => { e.currentTarget.style.display = 'none' }} />
               <span className="absolute inset-0 flex items-center justify-center text-zinc-900 font-bold text-xs -z-10">S</span>
            </div>
            <div className="flex flex-col">
              <span className="text-sm font-semibold tracking-tight">SizeSnap</span>
            </div>
          </div>
          <button onClick={() => setMobileMenuOpen(false)} className="lg:hidden p-1 text-zinc-500 hover:text-zinc-900 dark:hover:text-white">
            ✕
          </button>
        </div>

        <div className="px-3 pb-4 flex-1 overflow-y-auto mt-4">
          <nav className="space-y-0.5">
            {navItems.map((item) => {
              const isActive = pathname === item.href || (pathname.startsWith(item.href) && item.href !== '/admin')
              return (
                <a
                  key={item.name}
                  href={item.href}
                  className={`flex items-center px-3 py-2 text-sm rounded-md transition-colors ${
                    isActive
                      ? 'bg-zinc-200/50 dark:bg-zinc-800/50 text-zinc-900 dark:text-zinc-50 font-medium'
                      : 'text-zinc-600 dark:text-zinc-400 hover:bg-zinc-100 dark:hover:bg-zinc-900 hover:text-zinc-900 dark:hover:text-zinc-50'
                  }`}
                >
                  <item.icon className={`mr-3 w-4 h-4 ${isActive ? 'text-zinc-900 dark:text-white' : 'text-zinc-400'}`} strokeWidth={isActive ? 2 : 1.5} />
                  {item.name}
                </a>
              )
            })}
          </nav>
        </div>

        <div className="p-4 border-t border-zinc-200 dark:border-zinc-800">
          <div className="flex items-center justify-between group">
            <div className="flex items-center gap-3 overflow-hidden">
              <div className="w-8 h-8 rounded-full bg-zinc-200 dark:bg-zinc-800 flex items-center justify-center text-zinc-600 dark:text-zinc-300 text-xs font-medium border border-zinc-300 dark:border-zinc-700">
                {user.email ? user.email.charAt(0).toUpperCase() : 'A'}
              </div>
              <div className="truncate">
                <p className="text-xs font-medium truncate">{user.email}</p>
                <p className="text-[10px] text-zinc-500">Admin</p>
              </div>
            </div>
            <div className="flex gap-1 shrink-0">
               <a 
                 href="/"
                 target="_blank"
                 rel="noreferrer"
                 className="p-2 text-zinc-400 hover:text-zinc-900 dark:hover:text-white rounded-md hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
                 title="View Website"
               >
                 <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"/><path d="M2 12h20"/></svg>
               </a>
               <button 
                 onClick={() => auth.signOut()}
                 className="p-2 text-zinc-400 hover:text-zinc-900 dark:hover:text-white rounded-md hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
                 title="Sign Out"
               >
              <LogOut className="w-4 h-4" />
            </button>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden bg-white dark:bg-[#0A0A0A] border-l border-transparent sm:border-zinc-200 sm:dark:border-zinc-800 lg:border-l-0 sm:rounded-tl-2xl lg:rounded-none lg:shadow-none shadow-sm shadow-zinc-200/20">
        <header className="h-14 flex items-center justify-between px-6 border-b border-zinc-200 dark:border-zinc-800 bg-white/80 dark:bg-[#0A0A0A]/80 backdrop-blur-md sticky top-0 z-20">
          <div className="flex items-center gap-3">
            <button 
              onClick={() => setMobileMenuOpen(true)}
              className="lg:hidden -ml-2 p-2 text-zinc-600 dark:text-zinc-400 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-md"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="4" x2="20" y1="12" y2="12"/><line x1="4" x2="20" y1="6" y2="6"/><line x1="4" x2="20" y1="18" y2="18"/></svg>
            </button>
            <h1 className="text-sm font-semibold capitalize">
              {pathname === '/admin' ? 'Overview' : pathname.split('/').pop()?.replace('-', ' ')}
            </h1>
          </div>
          <div className="flex items-center">
             <div className="flex items-center gap-2 text-[11px] font-medium text-zinc-500 dark:text-zinc-400 px-2 py-1 rounded-md border border-zinc-200 dark:border-zinc-800 bg-[#FAFAFA] dark:bg-black">
               <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
               Production
             </div>
          </div>
        </header>
        <div className="flex-1 overflow-y-auto p-6 lg:p-8">
          <div className="max-w-6xl mx-auto">
            {children}
          </div>
        </div>
      </main>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { signInWithEmailAndPassword } from 'firebase/auth'
import { auth, db } from '@/lib/firebase'
import { doc, setDoc, serverTimestamp } from 'firebase/firestore'
import { useRouter } from 'next/navigation'
import { Lock, Mail, AlertCircle, ArrowRight } from 'lucide-react'

export default function AdminLogin() {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const router = useRouter()

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setLoading(true)

    try {
      if (!auth) throw new Error('Firebase configuration missing (auth is undefined)')

      const cred = await signInWithEmailAndPassword(auth, email, password)

      // Enforce single active device per user
      const sessionId = crypto.randomUUID()
      localStorage.setItem('sizesnap_admin_session', sessionId)

      if (db) {
        try {
          const setDocPromise = setDoc(doc(db, 'admin_settings', 'active_session'), {
            sessionId,
            lastLogin: serverTimestamp(),
            uid: cred.user.uid
          })

          const timeoutPromise = new Promise((_, reject) => 
            setTimeout(() => reject(new Error("Timeout: Firestore write taking too long.")), 3000)
          )

          await Promise.race([setDocPromise, timeoutPromise])
        } catch (firestoreError) {
          console.warn("Could not save session to Firestore (check rules). Skipping single-device enforcement.", firestoreError)
        }
      }

      router.push('/admin')
    } catch (err: any) {
      setError(`${err.code || 'Error'}: ${err.message}.`)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#FAFAFA] dark:bg-black p-4 font-sans text-zinc-900 dark:text-zinc-100">
      <div className="max-w-[400px] w-full bg-white dark:bg-[#0A0A0A] p-8 border border-zinc-200 dark:border-zinc-800 rounded-xl shadow-sm">
        <div className="mb-8">
          <div className="relative w-10 h-10 mb-6 rounded-md overflow-hidden bg-white border border-zinc-200 dark:border-zinc-800 flex items-center justify-center shadow-sm">
            <img src="/logo.png" alt="SizeSnap Logo" className="w-full h-full object-contain" onError={(e) => { e.currentTarget.style.display = 'none' }} />
            <span className="absolute inset-0 flex items-center justify-center text-zinc-900 font-bold text-lg -z-10">S</span>
          </div>
          <h1 className="text-xl font-semibold tracking-tight">Sign in to SizeSnap</h1>
          <p className="text-sm text-zinc-500 dark:text-zinc-400 mt-1.5">Enter your admin credentials below</p>
        </div>

        {error && (
          <div className="bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-900/50 text-red-600 dark:text-red-400 p-3 rounded-md text-sm mb-6 flex items-start">
            <AlertCircle className="w-4 h-4 mr-2 shrink-0 mt-0.5" />
            <span className="leading-relaxed">{error}</span>
          </div>
        )}

        <form onSubmit={handleLogin} className="space-y-4">
          <div className="space-y-1.5">
            <label className="block text-sm font-medium text-zinc-700 dark:text-zinc-300">Email address</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="w-full px-3 py-2 bg-white dark:bg-black border border-zinc-200 dark:border-zinc-800 rounded-md focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-100 focus:border-zinc-900 dark:focus:border-zinc-100 transition-all outline-none text-sm placeholder:text-zinc-400"
              placeholder="admin@sizesnap.in"
            />
          </div>

          <div className="space-y-1.5">
            <label className="block text-sm font-medium text-zinc-700 dark:text-zinc-300">Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              className="w-full px-3 py-2 bg-white dark:bg-black border border-zinc-200 dark:border-zinc-800 rounded-md focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-100 focus:border-zinc-900 dark:focus:border-zinc-100 transition-all outline-none text-sm placeholder:text-zinc-400"
              placeholder="••••••••"
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-zinc-900 hover:bg-zinc-800 dark:bg-white dark:hover:bg-zinc-200 text-white dark:text-black text-sm font-medium py-2.5 rounded-md transition-colors disabled:opacity-70 flex items-center justify-center mt-2 group"
          >
            {loading ? (
              <div className="w-4 h-4 border-2 border-white/30 dark:border-black/30 border-t-white dark:border-t-black rounded-full animate-spin"></div>
            ) : (
              <>Sign In <ArrowRight className="w-4 h-4 ml-2 opacity-70 group-hover:translate-x-0.5 transition-transform" /></>
            )}
          </button>
        </form>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { auth, db } from '@/lib/firebase'
import { collection, query, where, getDocs, Timestamp, orderBy, limit } from 'firebase/firestore'
import { Users, Download, Activity, MessageSquare, Clock, ArrowUpRight } from 'lucide-react'

export default function AdminDashboard() {
  const [stats, setStats] = useState({
    totalVisitors: 0,
    todayVisitors: 0,
    totalDownloads: 0,
    feedbackCount: 0,
    organicClicks: null as number | null
  })

  const [toolStats, setToolStats] = useState<any[]>([])
  const [messages, setMessages] = useState<any[]>([])
  const [timeRange, setTimeRange] = useState<'24hr' | '7day' | '30day' | '3month'>('30day')
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true)
        const res = await fetch(`/api/admin/dashboard?timeRange=${timeRange}`)
        const data = await res.json()

        if (data.success) {
          setStats(data.stats)
          setToolStats(data.toolStats)
          setMessages(data.messages)
        }
      } catch (err) {
        console.warn("Network error or API failed:", err)
      } finally {
        setLoading(false)
      }
    }

    let unsubscribeAuth: any;
    if (auth) {
      import('firebase/auth').then(({ onAuthStateChanged }) => {
        unsubscribeAuth = onAuthStateChanged(auth, (user) => {
          if (user) fetchData();
          else window.location.href = '/admin/login';
        });
      });
    }
    return () => { if (unsubscribeAuth) unsubscribeAuth(); }
  }, [timeRange])

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
         <div>
            <h1 className="text-xl font-bold tracking-tight text-zinc-900 dark:text-zinc-50">Dashboard</h1>
            <p className="text-sm text-zinc-500 dark:text-zinc-400 mt-1">Overview of SizeSnap performance.</p>
         </div>
         <div className="flex bg-zinc-100 dark:bg-zinc-900/50 p-1 rounded-md border border-zinc-200 dark:border-zinc-800">
            {(['24hr', '7day', '30day', '3month'] as const).map(tr => (
               <button 
                 key={tr}
                 onClick={() => setTimeRange(tr)}
                 className={`px-3 py-1.5 text-xs font-medium rounded-sm transition-colors ${timeRange === tr ? 'bg-white dark:bg-zinc-800 text-zinc-900 dark:text-zinc-50 shadow-sm border border-zinc-200 dark:border-zinc-700' : 'text-zinc-600 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100'}`}
               >
                 {tr === '24hr' ? 'Today' : tr === '7day' ? '7d' : tr === '30day' ? '30d' : '3m'}
               </button>
            ))}
         </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <MetricCard title="Total Tool Uses" value={loading ? "..." : stats.totalVisitors} />
        <MetricCard title="Downloads" value={loading ? "..." : stats.totalDownloads} />
        <MetricCard title="Feedback" value={loading ? "..." : stats.feedbackCount} />
        <MetricCard title="Organic Clicks" value={stats.organicClicks === null ? "GSC Not Connected" : stats.organicClicks} isText={stats.organicClicks === null} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <div className="bg-white dark:bg-[#0A0A0A] rounded-lg border border-zinc-200 dark:border-zinc-800 flex flex-col">
          <div className="px-5 py-4 border-b border-zinc-200 dark:border-zinc-800">
             <h2 className="text-sm font-semibold">Top Tools</h2>
          </div>
          {loading ? (
             <div className="flex-1 flex items-center justify-center py-10"><div className="w-5 h-5 border-2 border-zinc-300 dark:border-zinc-700 border-t-zinc-900 dark:border-t-white rounded-full animate-spin"></div></div>
          ) : toolStats.length === 0 ? (
             <div className="text-center text-zinc-500 text-sm py-10">No data found for this period.</div>
          ) : (
             <div className="flex-1 overflow-y-auto max-h-[350px]">
               <table className="w-full text-sm text-left">
                  <thead className="text-xs text-zinc-500 bg-zinc-50 dark:bg-zinc-900/50 sticky top-0 border-b border-zinc-200 dark:border-zinc-800">
                     <tr>
                        <th className="px-5 py-3 font-medium">Tool Name</th>
                        <th className="px-5 py-3 font-medium text-right">Uses</th>
                     </tr>
                  </thead>
                  <tbody className="divide-y divide-zinc-100 dark:divide-zinc-800/50">
                     {toolStats.slice(0, 10).map((tool, i) => (
                        <tr key={i} className="hover:bg-zinc-50 dark:hover:bg-zinc-900/30 transition-colors">
                           <td className="px-5 py-3 font-medium capitalize text-zinc-900 dark:text-zinc-200">{tool.name.replace(/-/g, ' ')}</td>
                           <td className="px-5 py-3 text-right text-zinc-600 dark:text-zinc-400">{tool.count.toLocaleString()}</td>
                        </tr>
                     ))}
                  </tbody>
               </table>
             </div>
          )}
        </div>

        <div className="bg-white dark:bg-[#0A0A0A] rounded-lg border border-zinc-200 dark:border-zinc-800 flex flex-col">
          <div className="px-5 py-4 border-b border-zinc-200 dark:border-zinc-800 flex justify-between items-center">
             <h2 className="text-sm font-semibold">Recent Feedback</h2>
             <a href="/admin/feedback" className="text-xs text-blue-600 hover:underline">View All</a>
          </div>
          {loading ? (
             <div className="flex-1 flex items-center justify-center py-10"><div className="w-5 h-5 border-2 border-zinc-300 dark:border-zinc-700 border-t-zinc-900 dark:border-t-white rounded-full animate-spin"></div></div>
          ) : messages.length === 0 ? (
             <div className="text-center text-zinc-500 text-sm py-10">No messages received yet.</div>
          ) : (
             <div className="flex-1 overflow-y-auto max-h-[350px] divide-y divide-zinc-100 dark:divide-zinc-800/50">
               {messages.slice(0, 5).map((msg, i) => (
                  <div key={i} className="p-5 hover:bg-zinc-50 dark:hover:bg-zinc-900/30 transition-colors">
                     <div className="flex items-center justify-between mb-2 text-xs">
                        <span className="text-zinc-500">{msg.timestamp ? new Date(msg.timestamp).toLocaleDateString() : 'Just now'}</span>
                        <div className="flex items-center gap-2">
                          <span className={`px-2 py-0.5 rounded-sm text-[10px] font-medium ${msg.read ? 'bg-zinc-100 text-zinc-500 dark:bg-zinc-800' : 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400'}`}>{msg.read ? 'Read' : 'New'}</span>
                          <a href={msg.pageUrl} target="_blank" rel="noreferrer" className="flex items-center gap-1 text-zinc-600 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100 truncate max-w-[150px]" title={msg.pageUrl}>
                             {(() => {
                                try { return new URL(msg.pageUrl || 'https://sizesnap.in').pathname } 
                                catch { return msg.pageUrl || 'Unknown' }
                             })()} <ArrowUpRight className="w-3 h-3" />
                          </a>
                        </div>
                     </div>
                     <p className="text-sm text-zinc-800 dark:text-zinc-200 line-clamp-2">{msg.message}</p>
                  </div>
               ))}
             </div>
          )}
        </div>
      </div>
    </div>
  )
}

function MetricCard({ title, value, isText }: { title: string, value: any, isText?: boolean }) {
  return (
    <div className="p-5 rounded-lg border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-[#0A0A0A] flex flex-col">
      <h3 className="text-zinc-500 dark:text-zinc-400 text-xs font-medium tracking-wide uppercase">{title}</h3>
      <p className={`mt-2 tracking-tight ${isText ? 'text-sm font-medium text-zinc-500' : 'text-3xl font-semibold text-zinc-900 dark:text-zinc-50'}`}>{typeof value === 'number' ? value.toLocaleString() : value}</p>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { auth } from '@/lib/firebase'
import { Download, AlertTriangle, TrendingUp, Search, FileText, ArrowUp, ArrowDown, Bot, CheckCircle, MessageSquare, Activity, Target, Sparkles, Filter } from 'lucide-react'

export default function SEOManagement() {
  const [data, setData] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [timeRange, setTimeRange] = useState('28days')
  const [showAllOpps, setShowAllOpps] = useState(false)
  const [activeTab, setActiveTab] = useState('overview')
  const [toolFilter, setToolFilter] = useState('All')

  useEffect(() => {
    fetchData()
  }, [timeRange])

  const fetchData = async () => {
    try {
      setLoading(true)
      const res = await fetch(`/api/admin/seo?timeRange=${timeRange}`)
      const json = await res.json()
      setData(json)
    } catch (err) {
      console.error("Failed to fetch SEO data", err)
    } finally {
      setLoading(false)
    }
  }

  const generateAntigravityTask = () => {
    if (!data?.actionPlan || data.actionPlan.length === 0) {
      alert("No action plan available.");
      return;
    }
    const date = new Date().toISOString().split('T')[0]
    const { current, changes } = data.overview;
    const formatChange = (val: any) => {
       const num = parseFloat(val);
       if (isNaN(num) || num === 0) return '(No change)';
       return num > 0 ? `(+${val}%)` : `(${val}%)`;
    };

    let md = `# SizeSnap SEO Growth Task\n\n`;
    md += `**Project:** SizeSnap\n`;
    md += `**Period:** ${timeRange === '7days' ? '7 Days' : timeRange === '28days' ? '28 Days' : '3 Months'}\n`;
    md += `**Generated:** ${date}\n\n`;
    md += `## 1. Overall Performance Summary\n`;
    md += `- **Total Clicks:** ${current.clicks.toLocaleString()} ${formatChange(changes.clicks)}\n`;
    md += `- **Total Impressions:** ${current.impressions.toLocaleString()} ${formatChange(changes.impressions)}\n`;
    md += `- **Average CTR:** ${current.ctr}% ${formatChange(changes.ctr)}\n`;
    md += `- **Average Position:** ${current.position} (Change: ${parseFloat(changes.position) > 0 ? '+' : ''}${changes.position})\n\n`;
    md += `## 2. Priority SEO Opportunities\n\n`;

    data.actionPlan.forEach((opp: any, idx: number) => {
       md += `### ${idx + 1}. [${opp.priority} PRIORITY] Target: ${opp.page}\n`;
       md += `- **Query:** "${opp.query}"\n`;
       md += `- **Type:** ${opp.type.replace(/_/g, ' ')}\n`;
       md += `- **Evidence:** ${opp.impressions} impressions | ${opp.clicks} clicks | CTR: ${opp.ctr}% | Pos: ${opp.position}\n`;
       if (opp.uses > 0 || opp.feedback > 0) {
          md += `- **User Signals:** `;
          if (opp.uses > 0) md += `${opp.uses} recorded tool uses. `;
          if (opp.feedback > 0) md += `${opp.feedback} related user feedback requests. `;
          md += `\n`;
       }
       md += `- **Why it matters:** ${opp.reason.split(' Tool usage:')[0]}\n`;
       md += `- **Recommended Action:** ${opp.action}\n\n`;
    });

    md += `## 3. Strict Antigravity Instructions & Safety Rules\n`;
    md += `Please implement the above recommendations strictly adhering to the following rules:\n`;
    md += `1. **Inspect First**: Always read the existing codebase and relevant components before making changes.\n`;
    md += `2. **No Duplication**: Do not create duplicate pages. Prefer improving existing pages (e.g., adding deeper content, optimizing H1/titles).\n`;
    md += `3. **No Deletion**: Do not delete existing URLs or break existing routing.\n`;
    md += `4. **Internal Linking**: If adding internal links, use only real, existing routes on the site. Do not invent URLs.\n`;
    md += `5. **No Fake Data**: Do not invent facts, fake statistics, search volumes, or fake user reviews.\n`;
    md += `6. **No Keyword Stuffing**: Keep all content natural, helpful, and user-centric.\n`;
    md += `7. **Protect Existing Features**: Do not break the Google OAuth system, Firebase analytics, feedback systems, or existing tool functionalities.\n`;
    md += `8. **No Unapproved Deployments**: Do not automatically deploy to production. Prepare recommendations for review.\n\n`;

    md += `## 4. Final Verification Checklist\n`;
    md += `- [ ] Code changes implemented according to recommendations.\n`;
    md += `- [ ] \`npm run lint\` passes with no new errors.\n`;
    md += `- [ ] \`npm run build\` successfully compiles the optimized production build.\n`;
    md += `- [ ] Affected pages tested locally (no crashes/UI breaks).\n`;
    md += `- [ ] Git diff reviewed to ensure no unintended breakages.\n`;

    const blob = new Blob([md], { type: 'text/markdown' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `SizeSnap-SEO-Task-${date}.md`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  const updateActionStatus = async (opp: any, newStatus: string) => {
