            />
            Print Name & Date on Photo
          </label>
        </div>

        {includeDateStamp && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">
            <div>
              <label className="block text-[11px] font-semibold text-slate-600 dark:text-slate-400 mb-1">
                Candidate Full Name
              </label>
              <input
                type="text"
                value={candidateName}
                onChange={(e) => setCandidateName(e.target.value)}
                placeholder="e.g. RAHUL KUMAR SHARMA"
                className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-600 rounded-xl text-xs text-slate-900 dark:text-white uppercase font-medium focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-[11px] font-semibold text-slate-600 dark:text-slate-400 mb-1">
                Date of Photo (DOP)
              </label>
              <input
                type="date"
                value={photoDate}
                onChange={(e) => setPhotoDate(e.target.value)}
                className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-600 rounded-xl text-xs text-slate-900 dark:text-white font-medium focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
          </div>
        )}
      </div>

      {/* Multi-Slot Upload Matrix */}
      <div className="mt-6 space-y-4">
        <div className="flex items-center justify-between">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
            3. Upload Your Raw Photos & Documents:
          </label>
          <span className="text-xs text-slate-500 dark:text-slate-400">
            Completed: <strong>{allReadyCount}</strong> of {selectedExam.slots.length}
          </span>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {selectedExam.slots.map((slot, index) => {
            const state = slotStates[slot.id] || { status: 'empty' }
            const isReady = state.status === 'ready'
            const isProcessing = state.status === 'processing'

            return (
              <div
                key={slot.id}
                className={`p-4 rounded-2xl border transition-all flex flex-col justify-between gap-3 ${
                  isReady
                    ? 'border-emerald-500/60 bg-emerald-50/20 dark:bg-emerald-950/10'
                    : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800/60'
                }`}
              >
                {/* Slot Header */}
                <div className="flex items-start justify-between gap-2">
                  <div className="flex items-center gap-2">
                    <span className="w-6 h-6 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 text-xs font-bold flex items-center justify-center">
                      {index + 1}
                    </span>
                    <div>
                      <h4 className="text-xs font-bold text-slate-900 dark:text-white">{slot.name}</h4>
                      <p className="text-[11px] text-slate-500 dark:text-slate-400">
                        Target: <span className="font-semibold text-blue-600 dark:text-blue-400">{slot.targetKbMin}KB – {slot.targetKbMax}KB</span> ({slot.aspectRatioLabel})
                      </p>
                    </div>
                  </div>

                  {isReady && (
                    <span className="inline-flex items-center gap-1 text-[11px] font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-100 dark:bg-emerald-950/60 px-2 py-0.5 rounded-full">
                      <CheckCircle className="w-3.5 h-3.5" />
                      {state.processedSizeKb} KB (Passed)
                    </span>
                  )}
                </div>

                {/* Upload or Preview Content */}
                <div className="flex items-center gap-3">
                  {/* Thumbnail / Upload Area */}
                  {isReady && state.processedUrl ? (
                    <div className="w-20 h-20 bg-slate-100 dark:bg-slate-900 rounded-xl overflow-hidden border border-slate-200 dark:border-slate-700 shrink-0 flex items-center justify-center p-1">
                      <img
                        src={state.processedUrl}
                        alt={slot.name}
                        className="max-h-full max-w-full object-contain rounded"
                      />
                    </div>
                  ) : (
                    <label className="w-full border-2 border-dashed border-slate-300 dark:border-slate-700 hover:border-blue-400 rounded-xl p-4 text-center cursor-pointer bg-slate-50/50 dark:bg-slate-800/30 flex items-center justify-center gap-2 transition">
                      <input
                        type="file"
                        accept="image/jpeg,image/png,image/webp"
                        onChange={(e) => {
                          if (e.target.files?.[0]) processSlotFile(slot, e.target.files[0])
                        }}
                        className="hidden"
                      />
                      <Upload className="w-4 h-4 text-slate-400" />
                      <span className="text-xs font-semibold text-slate-700 dark:text-slate-300">
                        {isProcessing ? 'Processing & Compressing...' : `Upload ${slot.name}`}
                      </span>
                    </label>
                  )}

                  {/* Actions when Ready */}
                  {isReady && (
                    <div className="flex-1 flex flex-col gap-2">
                      <p className="text-[11px] text-slate-500 dark:text-slate-400">
                        Auto-adjusted resolution to {slot.widthPx}x{slot.heightPx}px and size to {state.processedSizeKb}KB.
                      </p>
                      <div className="flex items-center gap-2">
                        <a
                          href={state.processedUrl || '#'}
                          download={`${slot.id}-${candidateName ? candidateName.replace(/\s+/g, '_') : 'file'}.jpg`}
                          className="px-3 py-1.5 bg-slate-900 dark:bg-white text-white dark:text-slate-900 hover:bg-slate-800 text-[11px] font-bold rounded-lg flex items-center gap-1.5 cursor-pointer shadow-xs transition"
                        >
                          <Download className="w-3.5 h-3.5" />
                          Download
                        </a>
                        <label className="px-2.5 py-1.5 border border-slate-300 dark:border-slate-600 text-slate-600 dark:text-slate-300 text-[11px] font-semibold rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer transition flex items-center gap-1">
                          <input
                            type="file"
                            accept="image/jpeg,image/png,image/webp"
                            onChange={(e) => {
                              if (e.target.files?.[0]) processSlotFile(slot, e.target.files[0])
                            }}
                            className="hidden"
                          />
                          <RefreshCw className="w-3 h-3" />
                          Change
                        </label>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )
          })}
        </div>
      </div>

      {/* Big Master Action: Download Complete Exam Pack */}
      <div className="mt-8 pt-6 border-t border-slate-200 dark:border-slate-800 flex flex-col sm:flex-row items-center justify-between gap-4">
        <div>
          <h4 className="text-sm font-bold text-slate-900 dark:text-white">
            Download {selectedExam.shortLabel} (Ready-to-Upload Bundle)
          </h4>
          <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
            Auto-downloads all completed files (photo, signature, etc.) individually to your device without requiring ZIP extraction.
          </p>
        </div>

        <button
          onClick={handleDownloadAllIndividually}
          disabled={allReadyCount === 0 || isZipping}
          className="w-full sm:w-auto px-6 py-3.5 bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 hover:from-blue-500 hover:to-purple-500 text-white font-bold rounded-2xl text-xs shadow-lg shadow-blue-500/25 flex items-center justify-center gap-2 cursor-pointer transition disabled:opacity-40 disabled:cursor-not-allowed"
        >
          <FolderArchive className="w-4 h-4" />
          {isZipping ? 'Downloading Files...' : `Download ${allReadyCount} Ready Files`}
        </button>
      </div>
    </div>
  )
}

'use client'
import { useState, useCallback, useRef, useEffect } from 'react'
import { Upload, Download, RefreshCw, CheckCircle, AlertCircle, Sliders, ShieldCheck, Cpu, Percent, Share2 } from 'lucide-react'
import CompareSlider from '@/components/CompareSlider'

interface Props {
  config: {
    maxKB?: number
  }
}

type Status = 'idle' | 'processing' | 'done' | 'error'

export default function ImageCompressTool({ config }: Props) {
  const [status, setStatus] = useState<Status>('idle')
  const [originalFile, setOriginalFile] = useState<File | null>(null)
  const [originalUrl, setOriginalUrl] = useState<string | null>(null)
  const [resultUrl, setResultUrl] = useState<string | null>(null)
  const [originalSize, setOriginalSize] = useState(0)
  const [resultSize, setResultSize] = useState(0)
  const [dragOver, setDragOver] = useState(false)
  const [errorMsg, setErrorMsg] = useState('')

  // Compression modes: 'quality' or 'size'
  const [mode, setMode] = useState<'quality' | 'size'>('quality')

  // Controls
  const [compressQuality, setCompressQuality] = useState<number>(75) // Default 75% quality
  const [targetKB, setTargetKB] = useState<number>(config.maxKB || 100)
  const [loadingStep, setLoadingStep] = useState(0)

  const fileInputRef = useRef<HTMLInputElement>(null)

  const loadingSteps = [
    'Reading image file...',
    'Analyzing color parameters...',
    'Quantizing visual pixels...',
    'Iterating resolution adjustments...',
    'Evaluating size limits...',
    'Finalizing byte buffers...'
  ]

  // Local GPU-Accelerated Canvas Compression
  const compressImage = useCallback(async (file: File, qualityPercent: number, targetSizeKB?: number) => {
    return new Promise<Blob>((resolve, reject) => {
      const reader = new FileReader()
      reader.onload = (event) => {
        const img = new Image()
        img.onload = async () => {
          try {
            let width = img.width
            let height = img.height

            // Limit huge dimensions to optimize processing speeds
            const maxDim = 1600
            if (width > maxDim || height > maxDim) {
              const ratio = Math.min(maxDim / width, maxDim / height)
              width = Math.round(width * ratio)
              height = Math.round(height * ratio)
            }

            const canvas = document.createElement('canvas')
            const ctx = canvas.getContext('2d')
            if (!ctx) {
              reject(new Error('Browser canvas context not available.'))
              return
            }

            canvas.width = width
            canvas.height = height
            ctx.drawImage(img, 0, 0, width, height)

            // Mode 1: Compress to exact KB limit using Binary Search
            if (mode === 'size' && targetSizeKB) {

              const testCompress = (testScale: number, testQuality: number): Promise<Blob | null> => {
                return new Promise((res) => {
                  canvas.width = Math.max(1, Math.round(width * testScale))
                  canvas.height = Math.max(1, Math.round(height * testScale))
                  ctx.clearRect(0, 0, canvas.width, canvas.height)
                  ctx.drawImage(img, 0, 0, canvas.width, canvas.height)
                  canvas.toBlob((b) => res(b), 'image/jpeg', testQuality)
                })
              }

              let bestBlob: Blob | null = null
              let bestDiff = Infinity

              // 1. Binary Search on Quality (Scale = 1.0)
              let qLow = 0.05
              let qHigh = 1.0

              for (let i = 0; i < 7; i++) {
                const qMid = (qLow + qHigh) / 2
                const blob = await testCompress(1.0, qMid)
                if (!blob) break
                const kb = blob.size / 1024

                if (kb <= targetSizeKB) {
                  const diff = targetSizeKB - kb
                  if (diff < bestDiff) {
                    bestDiff = diff
                    bestBlob = blob
                  }
                  qLow = qMid // Try higher quality to get closer to target
                } else {
                  qHigh = qMid // Size too large, lower quality
                }
              }

              // 2. If even at q=0.05 it's too big, Binary Search on Scale (Quality = 0.6)
              if (!bestBlob) {
                let sLow = 0.1
                let sHigh = 0.95
                bestDiff = Infinity

                for (let i = 0; i < 8; i++) {
                  const sMid = (sLow + sHigh) / 2
                  const blob = await testCompress(sMid, 0.6)
                  if (!blob) break
                  const kb = blob.size / 1024

                  if (kb <= targetSizeKB) {
                    const diff = targetSizeKB - kb
                    if (diff < bestDiff) {
                      bestDiff = diff
                      bestBlob = blob
                    }
                    sLow = sMid // Try larger scale
                  } else {
                    sHigh = sMid // Scale too large
                  }
                }
              }

              if (bestBlob) {
                resolve(bestBlob)
              } else {
                // Extreme fallback
                const extremeBlob = await testCompress(0.2, 0.2)
                if (extremeBlob && (extremeBlob.size / 1024) <= targetSizeKB) {
                   resolve(extremeBlob)
                } else {
                   reject(new Error('Cannot compress this image below target size.'))
                }
              }
            } else {
              // Mode 2: Simple Quality Compression (instant)
              try {
                canvas.toBlob((blob) => {
                  if (blob) {
                    resolve(blob)
                  } else {
                    reject(new Error('Failed to generate image blob.'))
                  }
                }, 'image/jpeg', qualityPercent / 100)
              } catch (err) {
                reject(err)
              }
            }
          } catch (error) {
            reject(error instanceof Error ? error : new Error('Unknown error during compression.'))
          }
        }
        img.onerror = () => reject(new Error('Corrupted image file.'))
        img.src = event.target?.result as string
      }
      reader.onerror = () => reject(new Error('Failed to read image stream.'))
      reader.readAsDataURL(file)
    })
  }, [mode])

  const processImage = useCallback(async (file: File, overrideQuality?: number, overrideKB?: number) => {
    if (!file.type.startsWith('image/')) {
      setErrorMsg('Invalid file type. Please upload a JPG, PNG, or WEBP image.')
      setStatus('error')
      return
    }

    if (file.size > 25 * 1024 * 1024) {
      setErrorMsg('File too large. Please upload an image under 25MB.')
      setStatus('error')
      return
    }

    setOriginalFile(file)
    // Clean old original URL if exists
    if (originalUrl) URL.revokeObjectURL(originalUrl)
    setOriginalUrl(URL.createObjectURL(file))

    setOriginalSize(file.size)
    setStatus('processing')
    setErrorMsg('')
    setLoadingStep(0)

    const interval = setInterval(() => {
      setLoadingStep(prev => (prev < 5 ? prev + 1 : prev))
    }, 200)

    const q = overrideQuality !== undefined ? overrideQuality : compressQuality
    const kb = overrideKB !== undefined ? overrideKB : targetKB

    try {
      const blob = await compressImage(file, q, kb)
      clearInterval(interval)

      if (resultUrl) URL.revokeObjectURL(resultUrl)

      setResultUrl(URL.createObjectURL(blob))
      setResultSize(blob.size)
      setStatus('done')

      // Fire confetti gamification!
      import('canvas-confetti').then((confetti) => {
        confetti.default({
          particleCount: 150,
          spread: 70,
          origin: { y: 0.6 },
          colors: ['#4F46E5', '#10B981', '#3B82F6']
        });
      });
    } catch (err: any) {
      clearInterval(interval)
      setErrorMsg(err.message || 'Compression failed. Try a different format.')
      setStatus('error')
    }
  }, [compressQuality, targetKB, compressImage, resultUrl, originalUrl])

  // Triggers processing immediately on control adjustments
  const handleQualityChange = (val: number) => {
    setCompressQuality(val)
    if (originalFile) processImage(originalFile, val, undefined)
  }

  const handleKBChange = (val: number) => {
    setTargetKB(val)
    if (originalFile) processImage(originalFile, undefined, val)
  }

  const handleModeChange = (newMode: 'quality' | 'size') => {
    setMode(newMode)
    if (originalFile) {
      // Re-trigger with temporary updated mode state
      setTimeout(() => {
        if (newMode === 'quality') {
          processImage(originalFile, compressQuality, undefined)
        } else {
          processImage(originalFile, undefined, targetKB)
        }
      }, 50)
    }
  }

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) processImage(file)
  }

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setDragOver(false)
    const file = e.dataTransfer.files?.[0]
    if (file) processImage(file)
  }, [processImage])

  const formatBytes = (bytes: number) => {
    if (bytes < 1024) return `${bytes} B`
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
    return `${(bytes / (1024 * 1024)).toFixed(2)} MB`
  }

  const handleReset = () => {
    setStatus('idle')
    setOriginalFile(null)
    if (originalUrl) URL.revokeObjectURL(originalUrl)
    setOriginalUrl(null)
    if (resultUrl) URL.revokeObjectURL(resultUrl)
    setResultUrl(null)
    setOriginalSize(0)
    setResultSize(0)
    setErrorMsg('')
    if (fileInputRef.current) fileInputRef.current.value = ''
  }

  const handleShare = async () => {
    if (!resultUrl || !originalFile) return
    try {
      const res = await fetch(resultUrl)
      const blob = await res.blob()
      const file = new File([blob], originalFile.name || 'image.jpg', { type: 'image/jpeg' })
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({
          files: [file],
          title: 'My Compressed Image - SizeSnap',
          text: 'I compressed my image using SizeSnap.in!',
        })
      } else {
        await navigator.clipboard.writeText("https://sizesnap.in")
        alert("Link copied to clipboard! You can paste and share it with your friends on WhatsApp.")
      }
    } catch (err) {
      console.error("Share failed", err)
    }
  }

  useEffect(() => {
    return () => {
      if (originalUrl) URL.revokeObjectURL(originalUrl)
      if (resultUrl) URL.revokeObjectURL(resultUrl)
    }
  }, [originalUrl, resultUrl])

  return (
    <div className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">
      {/* Top Banner */}
      <div className="bg-gradient-to-r from-indigo-600 to-blue-700 px-6 py-4 text-white flex flex-col sm:flex-row sm:items-center justify-between gap-2">
        <div>
          <h3 className="font-bold text-lg leading-tight">Smart Image Compressor</h3>
          <p className="text-indigo-100 text-xs mt-1">Shrink image file size locally in your browser.</p>
        </div>
        <div className="bg-white/15 px-3 py-1.5 rounded-lg backdrop-blur-sm border border-white/10 text-xs font-semibold self-start sm:self-auto">
          Mode: <span className="font-extrabold text-amber-300">{mode === 'quality' ? 'Quality Optimized' : `${targetKB}KB Target`}</span>
        </div>
      </div>

      <div className="p-6 space-y-6">
        {/* Toggle Mode */}
        {status !== 'processing' && (
          <div className="space-y-4">
            <div className="flex border-b border-gray-200">
              <button
                onClick={() => handleModeChange('quality')}
                className={`flex-1 pb-3 text-sm font-semibold transition-all ${
                  mode === 'quality'
                    ? 'border-b-2 border-indigo-600 text-indigo-600'
                    : 'text-gray-500 hover:text-gray-800'
                }`}
              >
                Compress by Quality
              </button>
              <button
                onClick={() => handleModeChange('size')}
                className={`flex-1 pb-3 text-sm font-semibold transition-all ${
                  mode === 'size'
                    ? 'border-b-2 border-indigo-600 text-indigo-600'
                    : 'text-gray-500 hover:text-gray-800'
                }`}
              >
                Compress to Target Size (KB)
              </button>
            </div>

            {/* Quality Slider Control */}
            {mode === 'quality' && (
              <div className="space-y-2 bg-gray-50/50 border border-gray-100 rounded-xl p-4 animate-fadeIn">
                <div className="flex items-center justify-between text-sm font-medium text-gray-700">
                  <span className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider text-gray-500">
                    <Percent className="w-4 h-4 text-indigo-600" />
                    Quality Level:
                  </span>
                  <span className="font-bold text-indigo-700">{compressQuality}%</span>
                </div>
                <input
                  type="range"
                  min={10}
                  max={95}
                  step={5}
                  value={compressQuality}
                  onChange={e => handleQualityChange(Number(e.target.value))}
                  className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                />
                <div className="flex justify-between text-[10px] text-gray-400 font-bold">
                  <span>SMALL FILE (Low Quality)</span>
                  <span>BALANCED</span>
                  <span>BEST QUALITY (High Size)</span>
                </div>
              </div>
            )}

            {/* Target Size Slider Control */}
            {mode === 'size' && (
              <div className="space-y-2 bg-gray-50/50 border border-gray-100 rounded-xl p-4 animate-fadeIn">
                <div className="flex items-center justify-between text-sm font-medium text-gray-700">
                  <span className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider text-gray-500">
                    <Sliders className="w-4 h-4 text-indigo-600" />
                    Max File Size Budget:
                  </span>
                  <div className="flex items-center gap-1.5">
                    <input
                      type="number"
                      value={targetKB}
                      min={10}
                      max={2000}
                      onChange={e => handleKBChange(Math.max(10, Math.min(2000, Number(e.target.value))))}
                      className="w-20 px-2 py-0.5 border text-center rounded-md text-sm font-bold text-indigo-700"
                    />
                    <span className="text-xs text-gray-500 font-semibold">KB</span>
                  </div>
                </div>
                <input
                  type="range"
                  min={10}
                  max={500}
                  step={5}
                  value={targetKB <= 500 ? targetKB : 500}
                  onChange={e => handleKBChange(Number(e.target.value))}
                  className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                />
                <div className="flex justify-between text-[10px] text-gray-400 font-bold">
                  <span>10 KB</span>
                  <span>250 KB</span>
                  <span>500 KB</span>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Privacy & Trust Badge */}
        {status === 'idle' && (
          <div className="mb-4 bg-emerald-50 dark:bg-emerald-500/10 border border-emerald-200 dark:border-emerald-800 rounded-xl p-3 flex items-center justify-center gap-2 animate-fadeIn">
            <ShieldCheck className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
            <span className="text-sm font-semibold text-emerald-800 dark:text-emerald-300">
              100% Private: Photos are processed locally on your device. Never uploaded to any server.
            </span>
          </div>
        )}

        {/* Upload Zone */}
        {status === 'idle' && (
          <div
            className={`border-2 border-dashed rounded-2xl p-10 text-center cursor-pointer transition-all ${
              dragOver
                ? 'border-indigo-500 bg-indigo-50/30 dark:bg-indigo-900/20'
                : 'border-gray-300 dark:border-zinc-700 hover:border-indigo-400 hover:bg-gray-50/30 dark:hover:bg-zinc-800/50'
            }`}
            onClick={() => fileInputRef.current?.click()}
            onDragOver={e => { e.preventDefault(); setDragOver(true) }}
            onDragLeave={() => setDragOver(false)}
            onDrop={handleDrop}
          >
            <Upload className="w-12 h-12 text-indigo-500 mx-auto mb-4 stroke-1.5" />
            <h4 className="font-bold text-gray-800 dark:text-zinc-100 text-base mb-1">
              Select Image to Compress
            </h4>
            <p className="text-xs text-gray-500 dark:text-zinc-400">Supports JPG, PNG, WEBP files up to 25MB</p>

            <button className="mt-4 px-5 py-2.5 bg-indigo-50 text-indigo-700 font-semibold text-sm rounded-xl hover:bg-indigo-100 transition-colors inline-flex items-center gap-2">
              Select Photo
            </button>

            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              className="hidden"
              onChange={handleFileChange}
            />
          </div>
        )}

        {/* Processing Spinner */}
        {status === 'processing' && (
          <div className="text-center py-10 bg-slate-50/40 rounded-2xl border border-gray-100 space-y-4 px-6">
            <RefreshCw className="w-12 h-12 text-indigo-600 mx-auto animate-spin stroke-1.5" />
            <div className="space-y-1">
              <h4 className="font-bold text-gray-800 text-base">Compressing File...</h4>
              <p className="text-xs text-indigo-600 font-semibold animate-pulse">
                {loadingSteps[loadingStep]}
              </p>
            </div>

            {/* Smooth animated progress bar */}
