        </div>
      </div>

      <div className="p-6 space-y-6">
        {/* Toggle Mode */}
        {status !== 'processing' && (
          <div className="space-y-4">
            <div className="flex border-b border-gray-200">
              <button
                onClick={() => setMode('quality')}
