                    >
                      <span className="block text-sm">{lvl.label}</span>
                      <span className={`block text-[9px] uppercase tracking-wider mt-0.5 ${compressLevel === lvl.val ? 'text-blue-100' : 'text-gray-400'}`}>{lvl.desc}</span>
