        {/* Privacy & Trust Badge */}
        {status === 'idle' && (
          <div className="mb-4 bg-emerald-50 dark:bg-emerald-500/10 border border-emerald-200 dark:border-emerald-800 rounded-xl p-3 flex items-center justify-center gap-2 animate-fadeIn">
