              </a>

              {/* Mobile Sticky Download */}
              <div className="sm:hidden fixed bottom-6 left-4 right-4 z-50 flex gap-2">
                <a
                  href={resultUrl}
                  download={`compressed-${originalFile?.name || 'document.pdf'}`}
