              </button>
            </div>
          </div>

          {/* Visual Page Grid */}
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
            {pages.map((page, idx) => (
              <div
                key={page.pageIndex}
                className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl p-3 shadow-xs hover:shadow-md transition flex flex-col items-center justify-between gap-3 group"
              >
                {/* Page Number & Delete */}
                <div className="w-full flex items-center justify-between text-xs text-slate-500 dark:text-slate-400">
                  <span className="font-semibold text-slate-800 dark:text-slate-200">Page {idx + 1}</span>
                  <button
                    onClick={() => deletePage(idx)}
                    className="p-1 text-slate-400 hover:text-red-500 rounded cursor-pointer transition"
                    title="Delete page"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>

                {/* Thumbnail with rotation */}
                <div className="w-full h-44 bg-slate-100 dark:bg-slate-900 rounded-xl overflow-hidden flex items-center justify-center p-2">
                  <img
                    src={page.thumbnailUrl}
                    alt={`Page ${idx + 1}`}
                    className="max-h-full max-w-full object-contain rounded transition-transform duration-300"
                    style={{ transform: `rotate(${page.rotation}deg)` }}
                  />
                </div>

                {/* Card Controls */}
                <div className="w-full flex items-center justify-between pt-1 border-t border-slate-100 dark:border-slate-700">
                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => rotatePage(idx, -90)}
                      className="p-1.5 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-lg cursor-pointer transition"
                      title="Rotate counter-clockwise"
                    >
                      <RotateCcw className="w-3.5 h-3.5" />
                    </button>
                    <button
                      onClick={() => rotatePage(idx, 90)}
                      className="p-1.5 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-lg cursor-pointer transition"
                      title="Rotate clockwise"
                    >
                      <RotateCw className="w-3.5 h-3.5" />
                    </button>
                  </div>

                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => movePage(idx, idx - 1)}
                      disabled={idx === 0}
                      className="p-1.5 hover:bg-slate-100 dark:hover:bg-slate-700 disabled:opacity-30 text-slate-600 dark:text-slate-300 rounded-lg cursor-pointer transition"
                      title="Move earlier"
                    >
                      <ArrowUp className="w-3.5 h-3.5" />
                    </button>
                    <button
                      onClick={() => movePage(idx, idx + 1)}
                      disabled={idx === pages.length - 1}
                      className="p-1.5 hover:bg-slate-100 dark:hover:bg-slate-700 disabled:opacity-30 text-slate-600 dark:text-slate-300 rounded-lg cursor-pointer transition"
                      title="Move later"
                    >
                      <ArrowDown className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Success Banner */}
          {status === 'done' && (
            <div className="p-4 bg-emerald-50 dark:bg-emerald-950/30 border border-emerald-500/20 rounded-xl text-emerald-800 dark:text-emerald-200 text-xs sm:text-sm flex items-center gap-3 animate-fadeIn">
              <CheckCircle className="w-5 h-5 text-emerald-600 shrink-0" />
              <span>
                Reorganized PDF saved and downloaded! Size: <strong>{Math.round(resultSize / 1024)} KB</strong>.
              </span>
            </div>
          )}
        </div>
      )}

      {/* Error state */}
      {status === 'error' && (
        <div className="mt-4 p-4 bg-red-50 dark:bg-red-950/30 border border-red-500/20 rounded-xl text-red-700 dark:text-red-300 text-xs sm:text-sm flex items-center gap-3">
          <AlertCircle className="w-5 h-5 text-red-500 shrink-0" />
          <span>{errorMsg || 'An error occurred while organizing the PDF.'}</span>
        </div>
      )}
    </div>
  )
}

'use client'
import { useState, useRef, useEffect } from 'react'
import {
  Wand2,
  Sparkles,
  Download,
  Sliders,
  Sun,
  Contrast,
  Zap,
  CheckCircle2,
  RefreshCw,
  FileText,
  Eye,
  RotateCcw
} from 'lucide-react'

type PresetMode = 'auto' | 'sharp_text' | 'remove_yellow' | 'doc_scan' | 'custom'

export default function PhotoClarifierTool({ config }: { config?: any }) {
  const [file, setFile] = useState<File | null>(null)
  const [previewUrl, setPreviewUrl] = useState<string | null>(null)
  const [mode, setMode] = useState<PresetMode>('auto')
  const [brightness, setBrightness] = useState<number>(15)
  const [contrast, setContrast] = useState<number>(25)
  const [sharpness, setSharpness] = useState<number>(35)
  const [deyellow, setDeyellow] = useState<number>(20)
  const [maxKb, setMaxKb] = useState<number>(100)
  const [isProcessing, setIsProcessing] = useState<boolean>(false)
  const [outputUrl, setOutputUrl] = useState<string | null>(null)
  const [outputSize, setOutputSize] = useState<number>(0)
  const [showOriginal, setShowOriginal] = useState<boolean>(false)

  const fileInputRef = useRef<HTMLInputElement>(null)
  const canvasRef = useRef<HTMLCanvasElement | null>(null)

  const handleFile = (selectedFile: File) => {
    setFile(selectedFile)
    const url = URL.createObjectURL(selectedFile)
    setPreviewUrl(url)
    setOutputUrl(null)
  }

  // Apply preset adjustments
  const handlePresetSelect = (preset: PresetMode) => {
    setMode(preset)
    if (preset === 'auto') {
      setBrightness(15)
      setContrast(25)
      setSharpness(35)
      setDeyellow(20)
    } else if (preset === 'sharp_text') {
      setBrightness(10)
      setContrast(45)
      setSharpness(65)
      setDeyellow(30)
    } else if (preset === 'remove_yellow') {
      setBrightness(25)
      setContrast(30)
      setSharpness(20)
      setDeyellow(60)
    } else if (preset === 'doc_scan') {
      setBrightness(35)
      setContrast(60)
      setSharpness(50)
      setDeyellow(80)
    }
  }

  const applyEnhancements = async () => {
    if (!previewUrl) return
    setIsProcessing(true)

    try {
      const img = new Image()
      img.src = previewUrl
      await new Promise((resolve) => {
        img.onload = resolve
      })

      const canvas = document.createElement('canvas')
      canvas.width = img.width
      canvas.height = img.height
      const ctx = canvas.getContext('2d')
      if (!ctx) throw new Error('Canvas not supported')

      ctx.drawImage(img, 0, 0)
      const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height)
      const data = imgData.data

      const bFactor = brightness * 1.2
      const cFactor = (259 * (contrast + 255)) / (255 * (259 - contrast))
      const dyFactor = deyellow / 100

      // Pixel manipulation pass
      for (let i = 0; i < data.length; i += 4) {
        let r = data[i]
        let g = data[i + 1]
        let b = data[i + 2]

        // 1. De-yellow / Color Cast Normalization
        if (dyFactor > 0) {
          const avg = (r + g + b) / 3
          // If pixel is background paper (bright but yellowish: r > b and g > b)
          if (r > 160 && g > 150) {
            r = r + (avg - r) * dyFactor
            g = g + (avg - g) * dyFactor
            b = b + (avg - b) * dyFactor
          }
        }

        // 2. Brightness
        r += bFactor
        g += bFactor
        b += bFactor

        // 3. Contrast
        r = cFactor * (r - 128) + 128
        g = cFactor * (g - 128) + 128
        b = cFactor * (b - 128) + 128

        data[i] = Math.min(255, Math.max(0, r))
        data[i + 1] = Math.min(255, Math.max(0, g))
        data[i + 2] = Math.min(255, Math.max(0, b))
      }

      ctx.putImageData(imgData, 0, 0)

      // 4. Sharpness Convolution Kernel (Unsharp Mask)
      if (sharpness > 0) {
        const sharpCanvas = document.createElement('canvas')
        sharpCanvas.width = canvas.width
        sharpCanvas.height = canvas.height
        const sharpCtx = sharpCanvas.getContext('2d')
        if (sharpCtx) {
          sharpCtx.drawImage(canvas, 0, 0)
          const srcData = ctx.getImageData(0, 0, canvas.width, canvas.height)
          const outData = sharpCtx.createImageData(canvas.width, canvas.height)
          const src = srcData.data
          const dst = outData.data
          const w = canvas.width
          const h = canvas.height

          const kWeight = (sharpness / 100) * 0.6
          const kernel = [
            0, -kWeight, 0,
            -kWeight, 1 + 4 * kWeight, -kWeight,
            0, -kWeight, 0
          ]

          for (let y = 1; y < h - 1; y++) {
            for (let x = 1; x < w - 1; x++) {
              const idx = (y * w + x) * 4
              for (let c = 0; c < 3; c++) {
                let val =
                  src[((y - 1) * w + x) * 4 + c] * kernel[1] +
                  src[(y * w + (x - 1)) * 4 + c] * kernel[3] +
                  src[(y * w + x) * 4 + c] * kernel[4] +
                  src[(y * w + (x + 1)) * 4 + c] * kernel[5] +
                  src[((y + 1) * w + x) * 4 + c] * kernel[7]

                dst[idx + c] = Math.min(255, Math.max(0, val))
              }
              dst[idx + 3] = src[idx + 3]
            }
          }
          sharpCtx.putImageData(outData, 0, 0)
          ctx.drawImage(sharpCanvas, 0, 0)
        }
      }

      // Convert to blob matching target maxKb using exact binary search
      const testCompress = async (testScale: number, testQuality: number) => {
         const tW = Math.max(1, Math.round(w * testScale))
         const tH = Math.max(1, Math.round(h * testScale))
         const tCanvas = document.createElement('canvas')
         tCanvas.width = tW
         tCanvas.height = tH
         const tCtx = tCanvas.getContext('2d')!
         tCtx.drawImage(canvas, 0, 0, w, h, 0, 0, tW, tH)
         return await new Promise<Blob | null>((res) => tCanvas.toBlob(res, 'image/jpeg', testQuality))
      }

      let bestBlob: Blob | null = null
      let bestDiff = Infinity

      // 1. Binary Search Quality
      let qLow = 0.05, qHigh = 1.0
      for (let i = 0; i < 7; i++) {
         const qMid = (qLow + qHigh) / 2
         const blob = await testCompress(1.0, qMid)
         if (!blob) break
         const sizeKb = blob.size / 1024
         if (sizeKb <= maxKb) {
            if (maxKb - sizeKb < bestDiff) {
               bestDiff = maxKb - sizeKb
               bestBlob = blob
            }
            qLow = qMid
         } else {
            qHigh = qMid
         }
      }

      // 2. Binary Search Scale
      if (!bestBlob) {
         let sLow = 0.1, sHigh = 0.95
         bestDiff = Infinity
         for (let i = 0; i < 7; i++) {
            const sMid = (sLow + sHigh) / 2
            const blob = await testCompress(sMid, 0.6)
            if (!blob) break
            const sizeKb = blob.size / 1024
            if (sizeKb <= maxKb) {
               if (maxKb - sizeKb < bestDiff) {
                  bestDiff = maxKb - sizeKb
                  bestBlob = blob
               }
               sLow = sMid
            } else {
               sHigh = sMid
            }
         }
      }

      if (!bestBlob) {
         bestBlob = await testCompress(0.2, 0.2)
      }

      if (bestBlob) {
        setOutputUrl(URL.createObjectURL(bestBlob))
        setOutputSize(Math.round(bestBlob.size / 1024))
      }
    } catch (err) {
      console.error(err)
    } finally {
      setIsProcessing(false)
    }
  }

  useEffect(() => {
    if (previewUrl) {
      applyEnhancements()
    }
  }, [previewUrl, brightness, contrast, sharpness, deyellow, maxKb])

  return (
    <div className="space-y-6">
      {/* Upload State */}
      {!previewUrl && (
        <div
          onClick={() => fileInputRef.current?.click()}
          className="border-2 border-dashed border-blue-400/60 dark:border-blue-500/30 rounded-3xl p-10 text-center cursor-pointer hover:bg-blue-50/40 dark:hover:bg-slate-800/40 transition-all group"
        >
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            className="hidden"
            onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0])}
          />
          <div className="w-16 h-16 rounded-2xl bg-gradient-to-tr from-blue-600 to-indigo-600 text-white mx-auto flex items-center justify-center mb-4 group-hover:scale-110 transition-transform shadow-lg shadow-blue-500/25">
            <Wand2 className="w-8 h-8" />
          </div>
          <h3 className="text-lg font-bold text-slate-900 dark:text-white">
            Upload Blurry or Dark Photo / Marksheet to Clarify
          </h3>
          <p className="text-xs text-slate-500 dark:text-slate-400 mt-1 max-w-md mx-auto">
            1-Click auto-contrast, unblur text, remove yellow shadows, and brighten dark phone camera scans. 100% private in-browser.
          </p>
        </div>
      )}

      {/* Main Studio Interface */}
      {previewUrl && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          {/* Controls Column */}
          <div className="lg:col-span-6 space-y-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 shadow-sm">
            <div className="flex items-center justify-between">
              <h3 className="text-base font-black text-slate-900 dark:text-white flex items-center gap-2">
                <Sparkles className="w-4 h-4 text-blue-600" />
                1-Click Enhancement Presets
              </h3>
              <button
                onClick={() => {
                  setPreviewUrl(null)
                  setOutputUrl(null)
                }}
                className="text-xs font-bold text-rose-600 hover:underline cursor-pointer"
              >
                Change Photo
              </button>
            </div>

            {/* Quick 1-Click Preset Buttons */}
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => handlePresetSelect('auto')}
                className={`p-3 rounded-2xl border text-left transition-all cursor-pointer ${
                  mode === 'auto'
                    ? 'bg-blue-50 dark:bg-blue-950/40 border-blue-600 text-blue-900 dark:text-blue-200 shadow-xs'
                    : 'bg-slate-50 dark:bg-slate-800/60 border-slate-200 dark:border-slate-700 hover:bg-slate-100'
                }`}
              >
                <span className="text-xs font-bold block flex items-center gap-1.5">
                  <Zap className="w-3.5 h-3.5 text-amber-500" />
                  Smart AI Auto-Fix
                </span>
                <span className="text-[10px] text-slate-500 block mt-0.5">
                  Balanced brightness & clarity
                </span>
              </button>

              <button
                onClick={() => handlePresetSelect('sharp_text')}
                className={`p-3 rounded-2xl border text-left transition-all cursor-pointer ${
                  mode === 'sharp_text'
                    ? 'bg-blue-50 dark:bg-blue-950/40 border-blue-600 text-blue-900 dark:text-blue-200 shadow-xs'
                    : 'bg-slate-50 dark:bg-slate-800/60 border-slate-200 dark:border-slate-700 hover:bg-slate-100'
                }`}
              >
                <span className="text-xs font-bold block flex items-center gap-1.5">
                  <FileText className="w-3.5 h-3.5 text-indigo-500" />
                  Unblur Marksheet Text
                </span>
                <span className="text-[10px] text-slate-500 block mt-0.5">
                  Sharpen edges & roll numbers
