          {/* 2. Signature Upload */}
          <div
            onClick={() => signInputRef.current?.click()}
            className={`border-2 border-dashed rounded-3xl p-8 text-center cursor-pointer transition-all ${
              signUrl
                ? 'border-emerald-500 bg-emerald-50/30 dark:bg-emerald-950/20'
