                  Download Clean Signature ({outputSize} KB)
                </a>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

'use client'
import { useState, useRef, useEffect } from 'react'
import { Upload, FileText, CheckCircle, RefreshCw, Download, AlertCircle, Maximize, Printer } from 'lucide-react'
import { PDFDocument } from 'pdf-lib'
import confetti from 'canvas-confetti'

interface Props {
  config?: any
}

type Status = 'idle' | 'processing' | 'done' | 'error'

export default function SmartAadharPrintTool({ config }: Props) {
  const [status, setStatus] = useState<Status>('idle')
  const [frontUrl, setFrontUrl] = useState<string | null>(null)
  const [backUrl, setBackUrl] = useState<string | null>(null)
  const [pdfUrl, setPdfUrl] = useState<string | null>(null)
  const [errorMsg, setErrorMsg] = useState('')

  const frontInputRef = useRef<HTMLInputElement>(null)
  const backInputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    return () => {
      if (frontUrl) URL.revokeObjectURL(frontUrl)
      if (backUrl) URL.revokeObjectURL(backUrl)
      if (pdfUrl) URL.revokeObjectURL(pdfUrl)
    }
  }, [frontUrl, backUrl, pdfUrl])

  const handleFrontUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      if (frontUrl) URL.revokeObjectURL(frontUrl)
      setFrontUrl(URL.createObjectURL(file))
      setStatus('idle')
    }
  }

  const handleBackUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      if (backUrl) URL.revokeObjectURL(backUrl)
      setBackUrl(URL.createObjectURL(file))
      setStatus('idle')
    }
  }

  const generateA4Print = async () => {
    if (!frontUrl || !backUrl) {
      setErrorMsg('Please upload both Front and Back sides.')
      setStatus('error')
      return
    }

    setStatus('processing')
    try {
      const pdfDoc = await PDFDocument.create()

      // Standard A4 sizes in points (72 points per inch)
      // A4 = 210mm x 297mm = 595.28 x 841.89 points
      const A4_WIDTH = 595.28
      const A4_HEIGHT = 841.89
      const page = pdfDoc.addPage([A4_WIDTH, A4_HEIGHT])

      // Load Images
      const fetchImage = async (url: string) => {
        const res = await fetch(url)
        return res.arrayBuffer()
      }

      const [frontBytes, backBytes] = await Promise.all([
        fetchImage(frontUrl),
        fetchImage(backUrl)
      ])

      // Embed logic (Try JPG, fallback to PNG)
      let frontImg, backImg
      try {
        frontImg = await pdfDoc.embedJpg(frontBytes)
      } catch (e) {
        frontImg = await pdfDoc.embedPng(frontBytes)
      }
      try {
        backImg = await pdfDoc.embedJpg(backBytes)
      } catch (e) {
        backImg = await pdfDoc.embedPng(backBytes)
      }

      // Standard PVC Card size: 85.6mm x 53.98mm
      // 1 mm = 2.83465 points
      const cardWidth = 85.6 * 2.83465
      const cardHeight = 54.0 * 2.83465

      // Placement on A4: Top Center, some margin from top.
      const marginY = 80 // distance from top
      const gapY = 20 // gap between front and back
      const centerX = (A4_WIDTH - cardWidth) / 2

      // Draw Front
      page.drawImage(frontImg, {
        x: centerX,
        y: A4_HEIGHT - marginY - cardHeight,
        width: cardWidth,
        height: cardHeight,
      })

      // Draw Back (Below Front)
      page.drawImage(backImg, {
        x: centerX,
        y: A4_HEIGHT - marginY - cardHeight - gapY - cardHeight,
        width: cardWidth,
        height: cardHeight,
      })

      const pdfBytes = await pdfDoc.save()
      const blob = new Blob([pdfBytes], { type: 'application/pdf' })
      const newPdfUrl = URL.createObjectURL(blob)

      if (pdfUrl) URL.revokeObjectURL(pdfUrl)
      setPdfUrl(newPdfUrl)
      setStatus('done')

      confetti({
        particleCount: 100,
        spread: 70,
        origin: { y: 0.6 }
      })

    } catch (err: any) {
      console.error(err)
      setErrorMsg(err.message || 'Error generating PDF.')
      setStatus('error')
    }
  }

  const resetAll = () => {
    setFrontUrl(null)
    setBackUrl(null)
    setPdfUrl(null)
    setStatus('idle')
  }

  return (
    <div className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">
      <div className="bg-gradient-to-r from-blue-700 to-indigo-800 px-6 py-5 text-white flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h3 className="font-bold text-xl leading-tight flex items-center gap-2">
            <Printer className="w-5 h-5" /> Smart Aadhar Print Maker
          </h3>
          <p className="text-blue-100 text-sm mt-1">Perfectly align Front & Back of Aadhar/PAN on A4 sheet for standard PVC card printing.</p>
        </div>
      </div>

      <div className="p-6 md:p-8">
        {status === 'error' && (
          <div className="mb-6 p-4 bg-red-50 text-red-700 rounded-xl flex items-center gap-3 border border-red-100">
            <AlertCircle className="w-5 h-5 flex-shrink-0" />
            <p className="text-sm font-medium">{errorMsg}</p>
          </div>
        )}

        {status === 'done' && pdfUrl ? (
          <div className="text-center py-10">
            <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6">
              <CheckCircle className="w-10 h-10" />
            </div>
            <h3 className="text-2xl font-bold text-gray-900 mb-2">Print Ready!</h3>
            <p className="text-gray-500 mb-8">A4 PDF generated with exact 85x54mm PVC Card Dimensions.</p>

            <div className="flex flex-col sm:flex-row gap-3 max-w-sm mx-auto">
              <a 
                href={pdfUrl}
                download="Smart_Aadhar_Print.pdf"
                className="flex-1 py-3.5 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl shadow-md transition-colors flex items-center justify-center gap-2"
              >
                <Download className="w-5 h-5" /> Download A4 PDF
              </a>
              <button 
                onClick={resetAll}
                className="py-3.5 px-6 border-2 border-gray-200 text-gray-700 font-bold rounded-xl hover:bg-gray-50 transition-colors"
              >
                Make Another
              </button>
            </div>
          </div>
        ) : (
          <div className="space-y-8">
            <div className="grid md:grid-cols-2 gap-6">

              {/* FRONT UPLOAD */}
              <div className="space-y-3">
                <label className="block text-sm font-semibold text-gray-700">1. Upload Front Side</label>
                <div 
                  onClick={() => frontInputRef.current?.click()}
                  className={`relative aspect-video rounded-xl border-2 border-dashed flex flex-col items-center justify-center cursor-pointer transition-colors overflow-hidden ${frontUrl ? 'border-blue-400 bg-blue-50/50' : 'border-gray-300 bg-gray-50 hover:bg-gray-100'}`}
                >
                  {frontUrl ? (
                    <img src={frontUrl} alt="Front" className="absolute inset-0 w-full h-full object-contain p-2" />
                  ) : (
                    <>
                      <div className="w-12 h-12 bg-white rounded-full shadow-sm flex items-center justify-center mb-3">
                        <Upload className="w-6 h-6 text-blue-500" />
                      </div>
                      <span className="text-sm font-medium text-gray-600">Select Front Image</span>
                    </>
                  )}
                  <input type="file" accept="image/*" className="hidden" ref={frontInputRef} onChange={handleFrontUpload} />
                </div>
              </div>

              {/* BACK UPLOAD */}
              <div className="space-y-3">
                <label className="block text-sm font-semibold text-gray-700">2. Upload Back Side</label>
                <div 
                  onClick={() => backInputRef.current?.click()}
                  className={`relative aspect-video rounded-xl border-2 border-dashed flex flex-col items-center justify-center cursor-pointer transition-colors overflow-hidden ${backUrl ? 'border-blue-400 bg-blue-50/50' : 'border-gray-300 bg-gray-50 hover:bg-gray-100'}`}
                >
                  {backUrl ? (
                    <img src={backUrl} alt="Back" className="absolute inset-0 w-full h-full object-contain p-2" />
                  ) : (
                    <>
                      <div className="w-12 h-12 bg-white rounded-full shadow-sm flex items-center justify-center mb-3">
                        <Upload className="w-6 h-6 text-blue-500" />
                      </div>
                      <span className="text-sm font-medium text-gray-600">Select Back Image</span>
                    </>
                  )}
                  <input type="file" accept="image/*" className="hidden" ref={backInputRef} onChange={handleBackUpload} />
                </div>
              </div>

            </div>

            <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3">
              <Maximize className="w-5 h-5 text-indigo-600 flex-shrink-0 mt-0.5" />
              <div>
                <h4 className="font-semibold text-indigo-900 text-sm">Automated Resizing</h4>
                <p className="text-xs text-indigo-700 mt-1">Both images will be automatically converted to 85.6mm x 54.0mm (standard PVC card dimension) and placed perfectly in the center of an A4 sheet for easy printing.</p>
              </div>
            </div>

            <button
              onClick={generateA4Print}
              disabled={status === 'processing' || !frontUrl || !backUrl}
              className="w-full py-4 rounded-xl text-white font-bold text-lg shadow-lg flex items-center justify-center gap-2 transition-all bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {status === 'processing' ? (
                <><RefreshCw className="w-5 h-5 animate-spin" /> Generating A4 PDF...</>
              ) : (
                <><FileText className="w-5 h-5" /> Generate Print-Ready PDF</>
              )}
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'
import { useState, useRef, useEffect, useCallback } from 'react'
import {
  Fingerprint,
  Upload,
  Download,
  CheckCircle2,
  Sliders,
  Sparkles,
  ShieldCheck,
  RotateCw,
  Sun,
  Palette
} from 'lucide-react'

type InkType = 'black' | 'blue' | 'original'
type ThumbLabelType = 'left' | 'right' | 'none'

export default function ThumbImpressionResizerTool({ config }: { config?: any }) {
  const [file, setFile] = useState<File | null>(null)
  const [imageUrl, setImageUrl] = useState<string | null>(null)

  const [thumbLabel, setThumbLabel] = useState<ThumbLabelType>('left')
  const [inkColor, setInkColor] = useState<InkType>('blue')
  const [contrast, setContrast] = useState<number>(45) // 0 to 100
  const [ridgeSharpness, setRidgeSharpness] = useState<number>(35) // 0 to 100
  const [bgWhiten, setBgWhiten] = useState<number>(40) // 0 to 100
  const [targetKb, setTargetKb] = useState<number>(20) // Default 20KB for SSC/IBPS

  const [isProcessing, setIsProcessing] = useState<boolean>(false)
  const [outputUrl, setOutputUrl] = useState<string | null>(null)
  const [outputSize, setOutputSize] = useState<number>(0)

  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleUpload = (f: File) => {
    if (!f.type.startsWith('image/')) return
    setFile(f)
    setImageUrl(URL.createObjectURL(f))
  }

  const processThumb = useCallback(async () => {
    if (!imageUrl) return
    setIsProcessing(true)

    try {
      const img = new Image()
      img.crossOrigin = 'anonymous'
      await new Promise((resolve, reject) => {
        img.onload = resolve
        img.onerror = reject
        img.src = imageUrl
      })

      // Standard thumb impression aspect ratio: 4:3 (approx 400x300 px)
      const targetW = 400
      const targetH = 300
      const canvas = document.createElement('canvas')
      canvas.width = targetW
      canvas.height = targetH
      const ctx = canvas.getContext('2d')
      if (!ctx) throw new Error('Canvas not supported')

      // White background
      ctx.fillStyle = '#FFFFFF'
      ctx.fillRect(0, 0, targetW, targetH)

      // Fit image centered
      const scale = Math.min((targetW - 30) / img.width, (targetH - 45) / img.height, 1.2)
      const drawW = img.width * scale
      const drawH = img.height * scale
      const offsetX = (targetW - drawW) / 2
      const offsetY = (targetH - 30 - drawH) / 2

      ctx.drawImage(img, offsetX, offsetY, drawW, drawH)

      // Ridge Enhancement & Background Whitening Filter
      const imgData = ctx.getImageData(0, 0, targetW, targetH - 30)
      const data = imgData.data

      const threshold = 255 - (bgWhiten * 1.8) // Higher bgWhiten means higher threshold
      const contrastFactor = (259 * (contrast + 100)) / (100 * (259 - contrast))

      for (let i = 0; i < data.length; i += 4) {
        const r = data[i]
        const g = data[i + 1]
        const b = data[i + 2]

        // Grayscale luminance
        let gray = 0.299 * r + 0.587 * g + 0.114 * b

        // Apply contrast
        gray = contrastFactor * (gray - 128) + 128
        gray = Math.max(0, Math.min(255, gray))

        // Whiten background if lighter than threshold
        if (gray > threshold) {
          data[i] = 255
          data[i + 1] = 255
          data[i + 2] = 255
        } else {
          // Dark ink area (ridge)
          const inkIntensity = (threshold - gray) / threshold // 0 to 1

          if (inkColor === 'blue') {
            // Official stamp pad blue ink: #0F3B82
            data[i] = Math.round(255 - inkIntensity * (255 - 15))
            data[i + 1] = Math.round(255 - inkIntensity * (255 - 59))
            data[i + 2] = Math.round(255 - inkIntensity * (255 - 130))
          } else if (inkColor === 'black') {
            // Deep official black ink
            const darkVal = Math.round(gray * (1 - ridgeSharpness / 120))
            data[i] = darkVal
            data[i + 1] = darkVal
            data[i + 2] = darkVal
          } else {
            // Original enhanced
            data[i] = Math.max(0, Math.min(255, r * (1 + contrast / 100)))
            data[i + 1] = Math.max(0, Math.min(255, g * (1 + contrast / 100)))
            data[i + 2] = Math.max(0, Math.min(255, b * (1 + contrast / 100)))
          }
        }
      }

      ctx.putImageData(imgData, 0, 0)

      // Bottom Label (Optional Left/Right Thumb)
      if (thumbLabel !== 'none') {
        ctx.fillStyle = '#F8FAFC'
        ctx.fillRect(0, targetH - 28, targetW, 28)
        ctx.strokeStyle = '#E2E8F0'
        ctx.lineWidth = 1
        ctx.beginPath()
        ctx.moveTo(0, targetH - 28)
        ctx.lineTo(targetW, targetH - 28)
        ctx.stroke()

        ctx.fillStyle = '#1E293B'
        ctx.font = 'bold 11px Inter, Arial, sans-serif'
        ctx.textAlign = 'center'
        ctx.textBaseline = 'middle'
        const labelText =
          thumbLabel === 'left' ? 'LEFT THUMB IMPRESSION (LTI)' : 'RIGHT THUMB IMPRESSION (RTI)'
        ctx.fillText(labelText, targetW / 2, targetH - 14)
      }

      // Outer border
      ctx.strokeStyle = '#CBD5E1'
      ctx.lineWidth = 1
      ctx.strokeRect(0, 0, targetW, targetH)

      // Compress under target KB
      let minQ = 0.3
      let maxQ = 0.95
      let bestBlob: Blob | null = null

      for (let i = 0; i < 5; i++) {
        const mid = (minQ + maxQ) / 2
        const blob = await new Promise<Blob | null>((res) =>
          canvas.toBlob(res, 'image/jpeg', mid)
        )
        if (!blob) break
        const sizeKb = blob.size / 1024
        bestBlob = blob
        if (sizeKb > targetKb) maxQ = mid
        else minQ = mid
      }

      // Emergency scale down fallback
      if (bestBlob && bestBlob.size / 1024 > targetKb) {
        let emergencyScale = 0.9
        while (bestBlob && bestBlob.size / 1024 > targetKb && emergencyScale > 0.1) {
          const ew = Math.max(1, Math.round(targetW * emergencyScale))
          const eh = Math.max(1, Math.round(targetH * emergencyScale))
          const eCanvas = document.createElement('canvas')
          eCanvas.width = ew
          eCanvas.height = eh
          const eCtx = eCanvas.getContext('2d')
          if (eCtx) {
            eCtx.drawImage(canvas, 0, 0, targetW, targetH, 0, 0, ew, eh)
            bestBlob = await new Promise<Blob | null>(res => eCanvas.toBlob(res, 'image/jpeg', 0.4))
          }
          emergencyScale *= 0.8
        }
      }

      if (bestBlob) {
        const outUrl = URL.createObjectURL(bestBlob)
        setOutputUrl(outUrl)
        const finalKb = Math.round(bestBlob.size / 1024)
        setOutputSize(finalKb)

        if (typeof window !== 'undefined') {
          window.dispatchEvent(
            new CustomEvent('sizesnap_file_ready', {
              detail: {
                id: Date.now().toString(),
                name: `thumb-impression-${thumbLabel}-${finalKb}kb.jpg`,
                url: outUrl,
                sizeKb: finalKb,
                type: 'Scanned Thumb Impression'
              }
            })
          )
        }
      }
    } catch (err) {
      console.error(err)
    } finally {
      setIsProcessing(false)
    }
  }, [imageUrl, thumbLabel, inkColor, contrast, ridgeSharpness, bgWhiten, targetKb])

  useEffect(() => {
    if (imageUrl) {
      processThumb()
    }
  }, [imageUrl, thumbLabel, inkColor, contrast, ridgeSharpness, bgWhiten, targetKb, processThumb])

  return (
    <div className="space-y-6">
      {/* Upload Screen */}
      {!imageUrl && (
        <div
          onClick={() => fileInputRef.current?.click()}
          className="border-2 border-dashed border-blue-300 dark:border-blue-700/50 hover:bg-blue-50/40 dark:hover:bg-slate-800/40 rounded-3xl p-10 text-center cursor-pointer transition-all"
        >
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            className="hidden"
            onChange={(e) => e.target.files?.[0] && handleUpload(e.target.files[0])}
          />
          <div className="w-16 h-16 rounded-2xl bg-gradient-to-tr from-blue-600 to-indigo-600 text-white mx-auto flex items-center justify-center mb-4 shadow-lg shadow-blue-500/20">
            <Fingerprint className="w-8 h-8" />
          </div>
          <h3 className="font-extrabold text-lg text-slate-900 dark:text-white">
            Upload Thumb Impression (LTI / RTI)
          </h3>
          <p className="text-xs text-slate-500 max-w-sm mx-auto mt-1">
            Auto-enhances fingerprint ridges, cleans paper shadows, and resizes to exact 10KB-20KB for SSC, IBPS, and NEET.
          </p>
          <button className="mt-5 px-5 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-500 text-white font-bold text-xs shadow-md shadow-blue-500/20 inline-flex items-center gap-2">
            <Upload className="w-4 h-4" /> Select Scanned Thumb Photo
          </button>
        </div>
      )}

      {/* Editor & Studio */}
      {imageUrl && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          {/* Controls Column */}
          <div className="lg:col-span-6 space-y-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 shadow-sm">
            <div className="flex items-center justify-between">
              <h3 className="text-base font-black text-slate-900 dark:text-white flex items-center gap-2">
                <Fingerprint className="w-4 h-4 text-blue-600" />
                Ridge &amp; Ink Studio
              </h3>
              <button
                onClick={() => {
                  setImageUrl(null)
                  setOutputUrl(null)
                }}
                className="text-xs font-bold text-rose-600 hover:underline cursor-pointer"
              >
                Change Photo
              </button>
            </div>

            {/* Thumb Label Preset */}
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-700 dark:text-slate-300 block">
                Select Thumb Impression Type
              </label>
              <div className="grid grid-cols-3 gap-2">
                {[
                  { id: 'left', label: 'Left Hand (LTI)' },
                  { id: 'right', label: 'Right Hand (RTI)' },
                  { id: 'none', label: 'No Printed Bar' }
                ].map((item) => (
                  <button
                    key={item.id}
                    onClick={() => setThumbLabel(item.id as ThumbLabelType)}
                    className={`py-2 px-2 rounded-xl text-xs font-bold transition-all cursor-pointer text-center ${
                      thumbLabel === item.id
                        ? 'bg-blue-600 text-white shadow-xs'
                        : 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300'
                    }`}
                  >
                    {item.label}
                  </button>
                ))}
              </div>
            </div>

            {/* Ink Color Selector */}
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-700 dark:text-slate-300 flex items-center gap-1.5">
                <Palette className="w-3.5 h-3.5 text-blue-600" />
                Official Ink Color
              </label>
              <div className="grid grid-cols-3 gap-2">
                {[
                  { id: 'blue', label: 'Official Blue Ink', color: 'bg-blue-600' },
                  { id: 'black', label: 'Pure Black Ink', color: 'bg-slate-900' },
                  { id: 'original', label: 'Original Scan', color: 'bg-slate-400' }
                ].map((item) => (
                  <button
                    key={item.id}
                    onClick={() => setInkColor(item.id as InkType)}
                    className={`py-2 px-2 rounded-xl text-xs font-bold transition-all cursor-pointer flex items-center justify-center gap-2 border ${
                      inkColor === item.id
                        ? 'bg-blue-50 dark:bg-blue-950/40 border-blue-600 text-blue-900 dark:text-blue-200'
                        : 'bg-white dark:bg-slate-800 border-slate-200 text-slate-700'
                    }`}
                  >
                    <span className={`w-3 h-3 rounded-full ${item.color}`} />
                    {item.label}
                  </button>
                ))}
              </div>
            </div>

            {/* Sliders: Ridge Sharpness & Clean Paper */}
            <div className="space-y-4 pt-2 border-t border-slate-100 dark:border-slate-800">
              <div className="space-y-1">
                <div className="flex items-center justify-between text-xs font-bold text-slate-700 dark:text-slate-300">
                  <span className="flex items-center gap-1.5">
                    <Sun className="w-3.5 h-3.5 text-amber-500" /> Clean Paper Background
                  </span>
                  <span>{bgWhiten}%</span>
                </div>
                <input
                  type="range"
                  min="0"
                  max="80"
                  value={bgWhiten}
                  onChange={(e) => setBgWhiten(Number(e.target.value))}
                  className="w-full accent-blue-600 cursor-pointer"
                />
              </div>

              <div className="space-y-1">
                <div className="flex items-center justify-between text-xs font-bold text-slate-700 dark:text-slate-300">
                  <span className="flex items-center gap-1.5">
                    <Sparkles className="w-3.5 h-3.5 text-indigo-500" /> Ridge Pattern Contrast
                  </span>
                  <span>{contrast}%</span>
                </div>
                <input
                  type="range"
                  min="0"
                  max="100"
                  value={contrast}
                  onChange={(e) => setContrast(Number(e.target.value))}
                  className="w-full accent-blue-600 cursor-pointer"
                />
              </div>
            </div>

            {/* Target Size Presets */}
            <div className="space-y-2 pt-2 border-t border-slate-100 dark:border-slate-800">
              <label className="text-xs font-bold text-slate-700 dark:text-slate-300 block">
                Target Maximum File Size
              </label>
              <div className="grid grid-cols-4 gap-2">
                {[10, 20, 50, 100].map((kb) => (
                  <button
                    key={kb}
                    onClick={() => setTargetKb(kb)}
                    className={`py-2 rounded-xl text-xs font-bold cursor-pointer transition-all ${
                      targetKb === kb
                        ? 'bg-blue-600 text-white shadow-xs'
                        : 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300'
                    }`}
                  >
                    ≤{kb}KB {kb === 20 && '⭐ (SSC)'}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Result Column */}
          <div className="lg:col-span-6 flex flex-col justify-between bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 shadow-sm">
            <div className="space-y-3 text-center">
              <div className="flex items-center justify-between">
                <span className="text-xs font-black uppercase tracking-wider text-slate-400">
                  Enhanced Scanned Result
                </span>
                <span className="text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-full border border-emerald-200 flex items-center gap-1">
                  <CheckCircle2 className="w-3 h-3" /> Form Upload Ready
                </span>
              </div>

              {/* Preview Box */}
              <div className="relative mx-auto min-h-[220px] max-h-[300px] flex items-center justify-center p-4 bg-slate-50 dark:bg-slate-800/40 rounded-2xl border border-slate-150 overflow-hidden">
                {outputUrl && (
                  <img
                    src={outputUrl}
                    alt="Enhanced Thumb Impression"
                    className="max-h-[240px] w-auto object-contain rounded-lg shadow-md border border-slate-300 bg-white"
                  />
                )}
              </div>

              {outputUrl && (
                <div className="flex items-center justify-center gap-3 text-xs pt-1">
                  <span className="px-3 py-1 rounded-full bg-emerald-50 text-emerald-800 font-bold border border-emerald-200">
                    Size: {outputSize} KB (Target: ≤{targetKb}KB)
                  </span>
                  <span className="px-3 py-1 rounded-full bg-blue-50 text-blue-800 font-bold border border-blue-200">
                    Aspect: 4 x 3 cm
                  </span>
                </div>
              )}
            </div>

            {outputUrl && (
              <div className="mt-4 pt-4 border-t border-slate-100 dark:border-slate-800">
                <a
                  href={outputUrl}
                  download={`thumb-impression-${thumbLabel}-${outputSize}kb.jpg`}
                  className="w-full py-3.5 px-4 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs shadow-md shadow-emerald-600/30 transition-all flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" />
                  Download Thumb Impression ({outputSize} KB JPG)
                </a>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  )
}
